def test_create_index(test_db):
    """Text creating index for a document."""
    text = "Test movie overview."
    metadata = {
            "imdb_id": "test_node",
            "popularity": 0.00,
            "budget": 0,
            "revenue": 0,
            "original_title": "Test Title",
            "stars": "Test Cast",
            "homepage": "http://example.com",
            "director": "Test Director",
            "tagline": "Test Tagline",
            "keywords": "Test Keywords",
            "overview": text,
            "runtime": "0",
            "genres": "Test Genre",
            "release_date": "2023-01-01",
            "vote_count": 0,
            "vote_average": 0,
            "release_year": 0,
            "character_tropes": "Test Tropes",
    }
    doc_id = "test_doc_1"
    documents = [Document(text=text, metadata=metadata, doc_id=doc_id)]
    # create index
    create_index(documents)
    assert documents[0].doc_id == doc_id, "Document ID should match the input"
    assert test_db.connect().execute(
        select(Movie).where(Movie.node_id == doc_id)
    ) is not None, "Movie should be added to the database"

def test_movie_from_csv():
    """Test loading movies from a CSV file."""
    csv_path: str = os.getenv("TEST_CSV_FILE")
    documents: list[Document] = load_movies_from_csv(csv_path)
    assert len(documents) > 0, "Documents should be loaded from CSV"
def test_search_ai():
    """Test the search_ai function."""
    # Test the search_ai function
    query = "What is the overview of Test Movie?"
    try:
        results = chat(query, getQEngine())
        assert results is not "Empty response", "Results should not be empty"
    except Exception as e:
        pytest.fail(f"search_ai failed with exception: {e}")
        